// SharkSight: one scan volume per checkpoint. Screens are added as the pipeline stages are rebuilt
// (classify → cluster → contextualize → elicit); each reads the shared checkpoint from useCheckpoint().
import { Navigate, Route, Routes } from "react-router-dom";
import { CheckpointProvider } from "@/state/checkpoint";
import { SweepControl } from "@/components/SweepControl";
import { AuditPanel } from "@/components/AuditPanel";
import { Scan } from "@/screens/scan/Scan";

export default function App() {
  return (
    <CheckpointProvider>
      <Routes>
        <Route path="/" element={<Scan key="volume" />} />
        <Route path="/structure" element={<Scan key="volume" mode="structure" />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      <SweepControl />
      <AuditPanel />
    </CheckpointProvider>
  );
}
// The two pages share one 3D volume: Evidence (raw sources) and Structure (what the AI made of them).
// Switching keeps the canvas mounted, so the comments fly into their clusters and back.
import { NavLink, useSearchParams } from "react-router-dom";
import { LogoMark } from "./Logo";
import "./pageswitch.css";

export function PageSwitch() {
  const [params] = useSearchParams();
  const q = params.toString() ? `?${params}` : "";
  return (
    <nav className="pageswitch" aria-label="Pages">
      <span className="brand"><LogoMark /><span className="brand-name">SharkSight</span></span>
      <NavLink to={`/${q}`} end>Evidence</NavLink>
      <NavLink to={`/structure${q}`}>Structure</NavLink>
    </nav>
  );
}
// API shapes for the checkpoint world (api/routers/scan.py).

export type CheckpointId = "cp1" | "cp2";
export type TrackState = "new" | "held" | "strengthened" | "weakened" | "lost";
export type SourceKind = "feedback" | "study" | "sales" | "option_list" | "research" | "web" | "reference";

export interface Checkpoint {
  id: CheckpointId;
  label: string;          // "JAN 26"
  cutoff: string;         // ISO date
  parent_id: CheckpointId | null;
  position: number;       // 1, 2
  sources: Record<SourceKind, { visible: number; new: number }>;
  acquire: { run_id: number; parent_run_id: number | null; tracks: Record<TrackState, number> } | null;
}

export interface PointsPayload {
  n: number;
  dict: { car: string[]; market: string[]; channel: string[]; engine: string[]; type: (string | null)[] };
  cols: {
    id: number[]; x: number[]; y: number[]; z: number[];
    car: number[]; market: number[]; channel: number[]; engine: number[]; type: number[];
    len: number[]; cp: number[];   // cp = checkpoint position at which the comment becomes visible
  };
}

export interface Comment {
  id: number; external_id: string; car: string; market: string; country: string; text: string;
  channel: string | null; engine: string | null; checkpoint: CheckpointId; ref: string;
  bmw_labels: { feedback_type: string | null; vfc_level2: string | null; vfc_level3: string | null }[];
}

export interface ResearchItem {
  id: number; cars: string[]; ring: "sales" | "study" | "options" | null; market: string | null; region: string | null; tier: string | null; topic: string | null;
  kind: string | null; entity: string | null; published_at: string | null; headline: string;
  yoy: number | null; value: number | null; unit: string | null; pair_key: string | null; url: string | null;
  new: boolean;
}

export interface OptionItem {
  id: number; car: string; code: string | null; name: string | null; category: string | null;
  availability: string | null; package: string | null;
}
export interface SalesRow { car: string; market: string; year: number; units: number | null; is_forecast: number }
export type StudyItem = { id: number; car: string; market: string; scale: string; item: string; z: number | null; value: number | null };

/** Anything on the scan the PM can open. */
export type Selection =
  | { kind: "comment"; id: number }
  | { kind: "study"; item: StudyItem }
  | { kind: "option"; item: OptionItem }
  | { kind: "sales"; item: SalesRow }
  | { kind: "research"; item: ResearchItem }
  | { kind: "cluster"; key: string }
  | { kind: "theme"; key: string }
  | { kind: "area"; key: string };

export interface SourcesPayload {
  checkpoint: CheckpointId;
  sales: SalesRow[];
  study: StudyItem[];
  options: OptionItem[];
  research: ResearchItem[];
  web: { n: number; new: number };
}

/* ---------------------------------------------------------------- structure & context (api/routers/structure.py) */
export interface ClusterNode {
  key: string; polarity: "like" | "improve" | null; category: string | null; state: TrackState | null;
  comments: number; signals: number; tail: boolean; aspects: Record<string, number> | null;
  by_line_market: Record<string, number> | null; x: number; y: number; z: number; theme: string | null;
  insight: { title: string; statement: string; need_type: string; quality_issue: boolean } | null;
}
export interface ThemeNode {
  key: string; title: string; statement: string; category: string; state: TrackState | null; comments: number;
  clusters: string[]; x: number; y: number; z: number;
}
export interface EvidenceEdge {
  src_type: string; src_id: string; dst_type: string; dst_id: string; relation: string; why: string | null; state: TrackState | null;
}
/** D-046: the markets an area's comments come from, with BMW's (stylized, weight-only) volume share, the latest
 *  cited public sales trend and whether BMW's file and public figures disagree there. */
export interface AreaMarket {
  label: string; bmw_volume_share: number;
  markets: { key: string; comments: number; bmw_share: number | null; conflict: boolean;
             trend: { yoy: number; period: string; region: string; tier: string | null; source_id: number } | null }[];
}
export interface AreaNode {
  id: number; key: string; title: string; need: string; kind: "improve" | "keep" | "emerging" | "quality";
  themes: string[]; why_now: string | null; open_questions: string[]; change_note: string | null; state: TrackState | null;
  metrics: { comments?: number; themes?: number; by_line_market?: Record<string, number>; evidence?: Record<string, number>;
             market?: AreaMarket };
}
export interface StructurePayload {
  checkpoint: CheckpointId; ready: boolean;
  stages?: Record<string, boolean>;
  clusters: ClusterNode[]; themes: ThemeNode[]; edges: EvidenceEdge[]; areas: AreaNode[];
  member: { ids: number[]; cluster: number[] };
  funnel: Record<"classify" | "cluster" | "contextualize" | "areas", Record<string, unknown> | null>;
}
export interface SignalRow {
  id: number; aspect: string | null; category: string; nature: string | null; want_kind: string | null; intensity: number | null;
  impact: string | null; occupant: string | null; need_statement: string | null; quote: string | null; quote_verified: number;
  explicit: number | null; future_cue: number | null; benchmark: string | null; benchmark_name: string | null; source_kind: string | null;
}
// Thin client for the local SharkSight API (`api/`, FastAPI). Every write carries the acting PM in X-Actor;
// the server records it in the append-only audit trail.
import { QueryClient } from "@tanstack/react-query";

const ACTOR_KEY = "successor.actor";
export const DEFAULT_ACTOR = "Atahan (PM)";

export function getActor(): string {
  try {
    return localStorage.getItem(ACTOR_KEY) || DEFAULT_ACTOR;
  } catch {
    return DEFAULT_ACTOR;
  }
}
export function setActor(name: string) {
  try {
    localStorage.setItem(ACTOR_KEY, name);
  } catch {
    /* private mode: fall back to the default actor */
  }
}

export class ApiError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  let res: Response;
  try {
    res = await fetch(path, {
      method,
      headers: { "Content-Type": "application/json", "X-Actor": getActor() },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new ApiError(0, "The local API isn't reachable. Start it with `uv run python -m api`.");
  }
  if (!res.ok) {
    let msg = `${res.status} ${res.statusText}`;
    try {
      const j = await res.json();
      if (typeof j.detail === "string") msg = j.detail;
      else if (Array.isArray(j.detail)) msg = j.detail.map((d: { msg?: string }) => d.msg).join("; ");
    } catch {
      /* keep status text */
    }
    throw new ApiError(res.status, msg);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

export const api = {
  get: <T,>(path: string) => request<T>("GET", path),
  post: <T,>(path: string, body?: unknown) => request<T>("POST", path, body ?? {}),
  put: <T,>(path: string, body?: unknown) => request<T>("PUT", path, body ?? {}),
  patch: <T,>(path: string, body?: unknown) => request<T>("PATCH", path, body ?? {}),
};

export function qs(params: Record<string, string | number | boolean | null | undefined>): string {
  const u = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== null && v !== "") u.set(k, String(v));
  const s = u.toString();
  return s ? `?${s}` : "";
}

export const queryClient = new QueryClient({
  defaultOptions: { queries: { staleTime: 15_000, refetchOnWindowFocus: false, retry: 1 } },
});

/** Everything a decision can change; refetched after every write. */
export function invalidateAll() {
  return queryClient.invalidateQueries();
}

/** Log a "view" access event once per browser session per requirement (StrictMode mounts effects twice in dev). */
const viewed = new Set<string>();
export function logView(reqId: string) {
  if (viewed.has(reqId)) return;
  viewed.add(reqId);
  api.post("/api/access", { action: "view", entity_type: "requirement", entity_id: reqId }).catch(() => viewed.delete(reqId));
}
// The checkpoint is app-wide state: every screen reads what is visible at the current checkpoint, and every screen
// can animate the change from the previous one (the sweep). The URL (?cp=) is the source of truth so a view can be
// linked; ← / → step between checkpoints anywhere in the app.
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { useQuery } from "@tanstack/react-query";
import { useSearchParams } from "react-router-dom";
import { api } from "@/lib/api";
import type { Checkpoint, CheckpointId } from "@/lib/types";

const ORDER: CheckpointId[] = ["cp1", "cp2"];
const isCp = (v: string | null): v is CheckpointId => v === "cp1" || v === "cp2";

interface Ctx {
  cp: CheckpointId;
  from: CheckpointId;        // checkpoint before the latest switch (equals cp when settled)
  sweepId: number;           // increments on every switch; screens restart their sweep on change
  setCp: (cp: CheckpointId) => void;
  checkpoints: Checkpoint[] | undefined;
  current: Checkpoint | undefined;
  position: number;          // 1 | 2
}

const CheckpointCtx = createContext<Ctx | null>(null);

export function CheckpointProvider({ children }: { children: ReactNode }) {
  const [params, setParams] = useSearchParams();
  const urlCp = params.get("cp");
  // No checkpoint in the URL: open at the first one and play the sweep to the latest once (the signature moment).
  const arrival = useRef(!isCp(urlCp));
  const cp: CheckpointId = isCp(urlCp) ? urlCp : "cp1";
  const prev = useRef<CheckpointId>(cp);
  const [from, setFrom] = useState<CheckpointId>(cp);
  const [sweepId, setSweepId] = useState(0);
  const { data: checkpoints } = useQuery({ queryKey: ["checkpoints"], queryFn: () => api.get<Checkpoint[]>("/api/checkpoints") });

  useEffect(() => {
    if (prev.current !== cp) {
      setFrom(prev.current);
      setSweepId((n) => n + 1);
      prev.current = cp;
    }
  }, [cp]);

  const setCp = useCallback(
    (next: CheckpointId) => {
      setParams((p) => { const q = new URLSearchParams(p); q.set("cp", next); return q; }, { replace: true });
    },
    [setParams],
  );

  useEffect(() => {
    if (!arrival.current || !checkpoints) return;
    const reduced = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    const t = window.setTimeout(() => { arrival.current = false; setCp(ORDER[ORDER.length - 1]); }, reduced ? 0 : 1200);
    return () => window.clearTimeout(t);
  }, [checkpoints, setCp]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("input, textarea, [contenteditable]")) return;
      const i = ORDER.indexOf(cp);
      if (e.key === "ArrowRight" && i < ORDER.length - 1) setCp(ORDER[i + 1]);
      if (e.key === "ArrowLeft" && i > 0) setCp(ORDER[i - 1]);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [cp, setCp]);

  const value = useMemo<Ctx>(() => {
    const current = checkpoints?.find((c) => c.id === cp);
    return { cp, from, sweepId, setCp, checkpoints, current, position: ORDER.indexOf(cp) + 1 };
  }, [cp, from, sweepId, setCp, checkpoints]);

  return <CheckpointCtx.Provider value={value}>{children}</CheckpointCtx.Provider>;
}

export function useCheckpoint(): Ctx {
  const c = useContext(CheckpointCtx);
  if (!c) throw new Error("useCheckpoint outside CheckpointProvider");
  return c;
}

export const CHECKPOINT_ORDER = ORDER;
// One colour per raw data type (validated categorical palette on black, dataviz reference dark steps).
export const TYPE_COLOR = { comment: "#3987e5", research: "#d95926", study: "#199e70", option: "#c98500", sales: "#d55181" } as const;

