                        ends={ends} onHover={p.onStructureHover ?? (() => {})} onSelect={p.onSelect} setCursor={setCursor} />
      )}
      {p.mode === "structure" && p.locked && p.focus == null && <Reticle at={p.locked} />}
      <ClassifyPulse ids={p.pulse} posOf={posOf} dpr={dpr * spread.grow} />
      </group>
