export const studyValue = (s: { scale: string; value: number | null }) =>
  s.value == null ? "" : s.scale === "dist_7" ? `${Math.round(s.value * 100)}% top-2` : `${s.value.toFixed(1)} / 10`;

export function Scene(p: SceneProps) {
  const { gl } = useThree();
  const dpr = gl.getPixelRatio();
  const commentMat = useMemo(() => contactMaterial(15 * dpr, TYPE_COLOR.comment), [dpr]);
  const researchMat = useMemo(() => contactMaterial(19 * dpr, TYPE_COLOR.research), [dpr]);
  const sweepRef = useRef<THREE.Group>(null);
  const setCursor = (on: boolean) => { gl.domElement.style.cursor = on ? "pointer" : ""; };
  const spread = useMemo(() => spreadOf(p.spread ?? 1), [p.spread]);
  const fit = useFit();

  /* comments */
  const comments = useMemo(() => {
    const c = p.points.cols, n = p.points.n;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
    }
    return attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) });
  }, [p.points]);
  useEffect(() => {
    const a = comments.getAttribute("aSel") as THREE.BufferAttribute;
    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
    a.needsUpdate = true;
  }, [comments, p.mask]);
  useEffect(() => { commentMat.uniforms.uHover.value = p.hoverComment ?? -1; }, [commentMat, p.hoverComment]);

  /* page 2 morph: each comment's target is its cluster centre (pulled in tight); unclustered comments stay and dim */
  useEffect(() => {
    const n = p.points.n, src = comments.getAttribute("position") as THREE.BufferAttribute;
        target.set([c.x + (x - c.x) * 0.07, c.y + (y - c.y) * 0.07, c.z + (z - c.z) * 0.07], i * 3);
        clustered[i] = 1;
      } else target.set([x, y, z], i * 3);
    }
    comments.setAttribute("aTarget", new THREE.BufferAttribute(target, 3));
    comments.setAttribute("aClustered", new THREE.BufferAttribute(clustered, 1));
  }, [comments, p.points, p.structure]);
  const morph = useRef(0);
  useFrame((_, dt) => {
    const goal = p.mode === "structure" && p.structure?.ready ? 1 : 0;
    if (morph.current === goal) return;
    const step = dt / 1.6;
    morph.current = goal > morph.current ? Math.min(goal, morph.current + step) : Math.max(goal, morph.current - step);
    const t = morph.current;
    commentMat.uniforms.uMorph.value = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  });

  /* research on the time ring */
  const research = useMemo(() => {
    const items = (p.sources?.research ?? []).filter((r) => !r.ring);
    const n = items.length;
    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    items.forEach((it, i) => {
      const a = timeAngle(it.published_at);
      const lane = (it.id % 7) / 7;
      const [x, , z] = polar(R.time + (lane - 0.5) * 0.1, a);
      pos.set([x, (lane - 0.5) * 0.05, z], i * 3);
      cp[i] = it.new ? 2 : 1; az[i] = a; size[i] = it.tier === "T1" ? 1.5 : 1.1; idx[i] = i;
    });
    return { items, geom: attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) }) };
  }, [p.sources]);

  /* public research about one car line, on that car's study / options / sales ring (D-042) */
  const studyMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.study), [dpr]);
  const optionMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.option), [dpr]);
  const salesMat = useMemo(() => contactMaterial(17 * dpr, TYPE_COLOR.sales), [dpr]);
  const carRings = useMemo(() => {
    const all = (p.sources?.research ?? []).filter((r) => r.ring);
    const build = (ring: "study" | "options" | "sales", radius: number) => {
      // one entry per (item × car); the 5 Series' China items go to the long-wheelbase G68 part of the sector
      const slots = new Map<string, { it: ResearchItem; car: string }[]>();
  /* comment id → its current place (raw position, or its cluster once the morph has run) */
  const posOf = useMemo(() => {
    const index = new Map(p.points.cols.id.map((id, i) => [id, i]));
    return (id: number): [number, number, number] | null => {
      const i = index.get(id);
      if (i == null) return null;
      const src = comments.getAttribute("position"), tgt = comments.getAttribute("aTarget");
      const m = commentMat.uniforms.uMorph.value as number;
      const a = [src.getX(i), src.getY(i), src.getZ(i)];
      if (!tgt || !m) return a as [number, number, number];
      return [a[0] + (tgt.getX(i) - a[0]) * m, a[1] + (tgt.getY(i) - a[1]) * m, a[2] + (tgt.getZ(i) - a[2]) * m];
    };
  }, [p.points, comments, commentMat]);

  /* where each evidence item sits on the rings (for the arcs on page 2) */
  const ends = useMemo(() => {
    const m = new Map<string, [number, number, number]>();
    const put = (g: THREE.BufferGeometry, items: { id: number }[]) => {
      const a = g.getAttribute("position");
      items.forEach((it, i) => m.set(`research:${it.id}`, [a.getX(i), a.getY(i), a.getZ(i)]));
    };
    put(research.geom, research.items);
    put(carRings.study.geom, carRings.study.items);
    put(carRings.options.geom, carRings.options.items);
    put(carRings.sales.geom, carRings.sales.items);
    for (const { item, tip } of studyLayout(p.sources?.study ?? [])) m.set(`study:${item.id}`, tip);
    for (const { item, at: pos } of optionLayout(p.sources?.options ?? [])) m.set(`option:${item.id}`, pos);
    return (type: string, id: string) => m.get(`${type}:${id}`) ?? null;
  }, [research, carRings, p.sources]);

  // the lock reticle rides with the focused layer, so it stays on the item as the layer rises
  const reticle = (id: LayerId) => (p.locked && p.focus === id ? <Reticle at={p.locked} /> : null);

  // car lines of the focused item, for the car names (G68 sits in the 5 Series sector)
  const focusLines = useMemo(() => {
    const s = p.selected;
    if (!s || p.focus == null) return null;
    let cars: string[] = [];
    if (s.kind === "comment") {
      const i = p.points.cols.id.indexOf(s.id);
      if (i >= 0) cars = [p.points.dict.car[p.points.cols.car[i]]];
    } else if (s.kind === "research") cars = s.item.cars;
    else if (s.kind === "study" || s.kind === "option" || s.kind === "sales") cars = [s.item.car];
    return new Set(cars.map((c) => (c === "G68" ? "G60" : c)));
  }, [p.selected, p.focus, p.points]);

  return (
    <>
      <CameraFit fit={fit} />
      {/* zoom goes toward the cursor and may come close, so any spot can be reached; right-drag (or Shift-drag) pans */}
      <OrbitControls makeDefault enablePan screenSpacePanning zoomToCursor minDistance={0.15} maxDistance={16 * spread.spread}
                     enableDamping dampingFactor={0.08} maxPolarAngle={Math.PI * 0.62} />
      <Navigator spread={spread.spread} nav={p.nav} fit={fit} />
      <SpreadCtx.Provider value={spread}>
      <group scale={spread.spread}>
      <Layer id="comment" focus={p.focus}>
        <points geometry={comments} material={commentMat} {...onComment} />
        {reticle("comment")}
      </Layer>
      <Rings sources={p.sources} focus={p.focus} focusLines={focusLines} filter={filter} onHover={p.onHover} onSelect={p.onSelect} setCursor={setCursor} slots={{
        research: <><points geometry={research.geom} material={researchMat} {...onResearch} />{reticle("research")}</>,
        study: <><points geometry={carRings.study.geom} material={studyMat} {...carRingHandlers(carRings.study, carRingSel.study, "Public rating")} />{reticle("study")}</>,
        option: <><points geometry={carRings.options.geom} material={optionMat} {...carRingHandlers(carRings.options, carRingSel.options, "Product news")} />{reticle("option")}</>,
        sales: (
          <>
            <points geometry={carRings.sales.geom} material={salesMat} {...carRingHandlers(carRings.sales, carRingSel.sales, "Public sales")} />
            <lineSegments geometry={salesSticks[0]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>
            {p.position >= 2 && <lineSegments geometry={salesSticks[1]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>}
            {reticle("sales")}
          </>
        ),
      }} />
      <group ref={sweepRef} visible={false}><SweepBlade /></group>
      {p.structure?.ready && (
        <StructureLayer data={p.structure} morph={morph} dpr={dpr * spread.grow} selected={p.selected ?? null} hoverKey={p.hoverKey ?? null}
                        ends={ends} onHover={p.onStructureHover ?? (() => {})} onSelect={p.onSelect} setCursor={setCursor} />
      )}
      {p.mode === "structure" && p.locked && p.focus == null && <Reticle at={p.locked} />}
      <ClassifyPulse ids={p.pulse} posOf={posOf} dpr={dpr * spread.grow} />
      </group>
      </SpreadCtx.Provider>
    </>
  );
}

/* ------------------------------------------------------------------------------------------- sweep + lock */
function SweepBlade() {
  const mat = useMemo(() => new THREE.ShaderMaterial({
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
  }), []);
  return (
    <>
      <mesh material={mat} position={[(R.sales + 0.1) / 2, 0, 0]}><planeGeometry args={[R.sales + 0.1, 1.4]} /></mesh>
      <mesh position={[(R.sales + 0.1) / 2, 0, 0]}><boxGeometry args={[R.sales + 0.1, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
    </>
  );
}

function Reticle({ at }: { at: [number, number, number] }) {

content.content:
// Moving through the scan volume. Spread scales the whole universe (layout positions) around a camera that stays put,
// while every mark keeps its size, so the space between contacts opens up on screen. The outer rings move past the
// view as it grows; scroll out or fly to reach them. Flying moves the camera and the orbit centre together:
// W/S forward and back, A/D sideways, Q/E down and up (Shift: faster), or hold the pad's buttons.
import { createContext, useContext, useEffect, useRef, type MutableRefObject, type PointerEvent as ReactPointerEvent } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { ArrowDown, ArrowUp, LocateFixed } from "lucide-react";
import * as THREE from "three";

export const SPREAD_MIN = 1, SPREAD_MAX = 4;
export const HOME: [number, number, number] = [0, 2.3, 5.3];

/** spread: layout scale; grow: how much marks grow with it (none); k: counter-scale for a mark inside the scaled world */
export interface Spread { spread: number; grow: number; k: number }
const make = (spread: number): Spread => ({ spread, grow: 1, k: 1 / spread });
export const spreadOf = make;
export const SpreadCtx = createContext<Spread>(make(1));
export const useSpread = () => useContext(SpreadCtx);

/** what the pad's buttons hold down; reset counts up once per press */
export interface NavInput { fwd: number; reset: number }
export const newNav = (): NavInput => ({ fwd: 0, reset: 0 });

const KEYS: Record<string, [number, number, number]> = {   // [forward, right, up]
  w: [1, 0, 0], s: [-1, 0, 0], a: [0, -1, 0], d: [0, 1, 0], e: [0, 0, 1], q: [0, 0, -1],
};
const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(TEXTAREA|SELECT)$/.test(t.tagName) ||
                               (t instanceof HTMLInputElement && !/^(range|checkbox|radio|button)$/.test(t.type)));

type Orbit = { target: THREE.Vector3; update: () => void };

export function Navigator({ spread, nav, fit }: { spread: number; nav: MutableRefObject<NavInput>; fit: () => number }) {
  const { camera } = useThree();
  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
  const held = useRef(new Set<string>());
  const fast = useRef(false);
  const home = useRef<{ t0: number; from: THREE.Vector3; fromT: THREE.Vector3 } | null>(null);
  const lastReset = useRef(nav.current.reset);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return;
      const key = e.key.toLowerCase();
      fast.current = e.shiftKey;
      if (KEYS[key]) { held.current.add(key); e.preventDefault(); }
    };
    const up = (e: KeyboardEvent) => { fast.current = e.shiftKey; held.current.delete(e.key.toLowerCase()); };
    const clear = () => held.current.clear();
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    window.addEventListener("blur", clear);
    return () => { window.removeEventListener("keydown", down); window.removeEventListener("keyup", up); window.removeEventListener("blur", clear); };
  }, []);

  const fwd = new THREE.Vector3(), right = new THREE.Vector3(), step = new THREE.Vector3();
  useFrame(({ clock }, dt) => {
    if (!controls) return;
    // reset: glide back to the opening view
    if (nav.current.reset !== lastReset.current) {
      lastReset.current = nav.current.reset;
      home.current = { t0: clock.elapsedTime, from: camera.position.clone(), fromT: controls.target.clone() };
    }
    if (home.current) {
      const h = home.current, p = Math.min(1, (clock.elapsedTime - h.t0) / 0.7), e = 1 - Math.pow(1 - p, 3);
      const goal = new THREE.Vector3(...HOME).setLength(fit());
      camera.position.lerpVectors(h.from, goal, e);
      controls.target.lerpVectors(h.fromT, new THREE.Vector3(), e);
      controls.update();
      if (p >= 1) home.current = null;
      return;
    }
    let f = nav.current.fwd, r = 0, u = 0;
    for (const k of held.current) { const [a, b, c] = KEYS[k]; f += a; r += b; u += c; }
    if (!f && !r && !u) return;
    camera.getWorldDirection(fwd);
    right.crossVectors(fwd, camera.up).normalize();
    const speed = 1.4 * spread * (fast.current ? 2.5 : 1) * Math.min(dt, 0.05);
    step.copy(fwd).multiplyScalar(f).addScaledVector(right, r).addScaledVector(camera.up, u).multiplyScalar(speed);
    camera.position.add(step);
    controls.target.add(step);
    controls.update();
  });
  return null;
}

/** Bottom-centre pad: the spread slider, hold-to-fly buttons and a reset. */
export function NavPad({ spread, onSpread, nav }: { spread: number; onSpread: (s: number) => void; nav: MutableRefObject<NavInput> }) {
  const hold = (dir: number) => ({
    onPointerDown: (e: ReactPointerEvent<HTMLButtonElement>) => { e.currentTarget.setPointerCapture(e.pointerId); nav.current.fwd = dir; },
    onPointerUp: () => { nav.current.fwd = 0; },
    onPointerCancel: () => { nav.current.fwd = 0; },
    onLostPointerCapture: () => { nav.current.fwd = 0; },
  });
  return (
    <div className="navpad" role="group" aria-label="Move through the universe">
      <label className="navpad-spread">
        <span>Spread</span>
        <input type="range" min={SPREAD_MIN} max={SPREAD_MAX} step={0.05} value={spread}
               onChange={(e) => onSpread(Number(e.target.value))} aria-valuetext={`${spread.toFixed(1)} times`} />
        <output className="num">{spread.toFixed(1)}×</output>
      </label>
      <div className="navpad-fly">
        <button type="button" title="Fly back (S)" aria-label="Fly back" {...hold(-1)}><ArrowDown size={14} /></button>
        <button type="button" title="Fly forward (W)" aria-label="Fly forward" {...hold(1)}><ArrowUp size={14} /></button>
        <button type="button" title="Reset view" aria-label="Reset view" onClick={() => { nav.current.reset++; }}><LocateFixed size={14} /></button>
      </div>
      <span className="navpad-hint">W/S fly · A/D side · Q/E down/up · right-drag pan · scroll zooms to cursor</span>
    </div>
  );
}
// Page 2 inside the scan volume: what the AI made of the raw evidence at the current checkpoint.
// Comment points have already flown into their clusters (the morph in Scene). This layer adds the structure on top:
// cluster nodes (blue = something to improve, white = something to keep; mark shape = track state: dot held,
// ring new, double ring strengthened, amber weakened, amber cross lost), theme halos around groups of clusters,
// potential requirement AREAS as diamonds floating above the themes they group, and — for the theme in focus —
// evidence arcs down to the exact research, study and option items on the rings.
import { createContext, useCallback, useContext, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Billboard, Html } from "@react-three/drei";
import * as THREE from "three";
import type { AreaNode, ClusterNode, Selection, StructurePayload, ThemeNode, TrackState } from "@/lib/types";
import type { Hover } from "../scan/Scene";
import { TYPE_COLOR } from "../scan/colors";
import { useSpread } from "../scan/navigate";

export const AREA_Y = 1.15;
const STATE_CODE: Record<TrackState, number> = { held: 0, new: 1, strengthened: 2, weakened: 3, lost: 4 };
const SRC_COLOR: Record<string, string> = { research: TYPE_COLOR.research, study: TYPE_COLOR.study, option: TYPE_COLOR.option };

const NODE_VERT = /* glsl */ `
attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
uniform float uScale, uShow, uHover;
varying float vState; varying float vPol; varying float vHov;
void main() {
  vState = aState; vPol = aPol; vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + vHov * 0.6) * uShow / -mv.z;
}`;
const NODE_FRAG = /* glsl */ `
uniform float uShow;
varying float vState; varying float vPol; varying float vHov;
void main() {
  vec2 c = gl_PointCoord - 0.5; float r = length(c);
  if (r > 0.5) discard;
  float dot = smoothstep(0.5, 0.44, r);
  float ring = smoothstep(0.5, 0.45, r) * smoothstep(0.34, 0.39, r);
  float dbl = ring + smoothstep(0.27, 0.23, r) * smoothstep(0.15, 0.19, r);
  float cross = (abs(c.x - c.y) < 0.06 || abs(c.x + c.y) < 0.06) && r < 0.45 ? 1.0 : 0.0;
  float a = vState < 0.5 ? dot : vState < 1.5 ? ring : vState < 2.5 ? dbl : vState < 3.5 ? dot : cross;
  vec3 base = vPol > 0.5 ? vec3(0.224, 0.529, 0.898) : vec3(0.93, 0.95, 0.97);
  vec3 amber = vec3(0.96, 0.65, 0.14);
  vec3 col = vState > 2.5 ? amber : base;
  col = mix(col, vec3(1.0), vHov);
  gl_FragColor = vec4(col, a * uShow * (vState > 3.5 ? 0.8 : 0.95));
}`;

/** Fades every material below it with the morph (structure appears as the comments arrive). The labels are DOM
 *  overlays (drei <Html>) that ignore `visible`, so the same fade goes to them as a CSS variable on the canvas
 *  container they live in, and they are taken out entirely at 0: on the Evidence page none of them show. */
function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
  const ref = useRef<THREE.Group>(null);
  // the element drei <Html> mounts its labels into (the event source, else the canvas's parent)
  const host = useThree((s) => ((s.events.connected as HTMLElement | undefined) ?? s.gl.domElement.parentElement) as HTMLElement | null);
  const last = useRef(-1);
  useFrame(() => {
    const g = ref.current;
    if (!g) return;
    const a = Math.max(0, (morph.current - 0.45) / 0.55);
    g.visible = a > 0.01;
    if (host && Math.abs(a - last.current) > 0.004) {
      last.current = a;
      host.style.setProperty("--structure-fade", a.toFixed(3));
      host.toggleAttribute("data-structure-off", a <= 0.01);
    }
    g.traverse((o) => {
      const mat = (o as THREE.Mesh).material;
      if (!mat) return;
      for (const m of Array.isArray(mat) ? mat : [mat]) {
        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uShow) m.uniforms.uShow.value = a; continue; }
        m.userData.baseOpacity ??= m.opacity;
        m.transparent = true;
        m.opacity = m.userData.baseOpacity * a;
      }
    });
  });
  return <group ref={ref}>{children}</group>;
}

/* ------------------------------------------------------------------------------------------- label collisions */
// Labels are placed in priority order: the label in focus or under the pointer first, then requirement areas by
// comments, then themes by comments. A label whose screen box would overlap one already placed is hidden (visibility
// only, so it stays measurable) until the view turns or its node is hovered. Checked a few times a second.
type Register = (key: string, prio: number) => (el: HTMLDivElement | null) => void;
const LabelCtx = createContext<Register>(() => () => {});
const PAD = 3;

function useLabelCollisions() {
  const labels = useRef(new Map<string, { el: HTMLDivElement; prio: number }>());
  const tick = useRef(0);
  const register = useCallback<Register>((key, prio) => (el) => {
    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
  }, []);
  useFrame(() => {
    if (tick.current++ % 6) return;
    const placed: DOMRect[] = [];
    const list = [...labels.current.values()].sort((a, b) => b.prio - a.prio);
    for (const { el, prio } of list) {
      const r = el.getBoundingClientRect();
      if (!r.width) continue;
      const hit = prio < FOCUS && placed.some((q) =>
        r.left < q.right + PAD && r.right > q.left - PAD && r.top < q.bottom + PAD && r.bottom > q.top - PAD);
      el.toggleAttribute("data-collide", hit);
      if (!hit) placed.push(r);
    }
  });
  return register;
}
const FOCUS = 1e9;          // focused or hovered: always shown
const AREA = 1e6;           // areas outrank themes

interface Props {
  data: StructurePayload;
  morph: MutableRefObject<number>;
  dpr: number;
  selected: Selection | null;
  hoverKey: string | null;
  ends: (type: string, id: string) => [number, number, number] | null;
  onHover: (h: Hover | null, key?: string | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
  setCursor: (on: boolean) => void;
}

export function StructureLayer(p: Props) {
  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);


  /* cluster nodes */
  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
  }), [p.dpr]);
  const nodes = useMemo(() => {
    const n = clusters.length;
    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    clusters.forEach((c, i) => {
      pos.set([c.x, c.y, c.z], i * 3);
      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
    g.computeBoundingSphere();
    return g;
  }, [clusters]);
  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));

  /* cluster → theme lines */
  const memberLines = useMemo(() => {
    const v: number[] = [];
    for (const c of clusters) {
      const t = c.theme ? themeOf[c.theme] : null;
      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [clusters, themeOf]);

  /* requirement areas float on a ring above the galaxy: each at an evenly spaced slot, in the order of its themes'
     bearing, so labels never pile up over the centre; stems tie every area to its themes below */
  const areas = useMemo(() => {
    const placed: { a: AreaNode; ts: ThemeNode[]; bearing: number }[] = [];
    for (const a of p.data.areas) {
      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
      if (!ts.length) continue;
      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
      placed.push({ a, ts, bearing: Math.atan2(z, x) });
    }
    placed.sort((m, n) => m.bearing - n.bearing);
    const n = placed.length || 1;
    return placed.map(({ a, ts }, i) => {
      const ang = (i / n) * Math.PI * 2 - Math.PI / 2;
      const r = a.kind === "quality" ? 0.35 : 1.05;
      const y = a.kind === "quality" ? AREA_Y - 0.25 : AREA_Y + (i % 2) * 0.12;   // alternate heights for neighbours
      return { a, ts, at: [r * Math.cos(ang), y, r * Math.sin(ang)] as [number, number, number] };
    });
  }, [p.data, themeOf]);
  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
  const stems = useMemo(() => {
    const v: number[] = [], hot: number[] = [];
    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
    return { all: g(v), hot: g(hot) };
  }, [areas, focusArea]);

  /* evidence arcs for the theme in focus */
  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
  const arcs = useMemo(() => {
    if (!focusTheme || !themeOf[focusTheme]) return [];
    const t = themeOf[focusTheme];
    const out: THREE.Line[] = [];
    for (const e of p.data.edges) {
      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
      const end = p.ends(e.src_type, e.src_id);
      if (!end) continue;
      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
      const pts = new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(40);
      const geom = new THREE.BufferGeometry().setFromPoints(pts);
      const contra = e.relation === "contradicts";
      const line = new THREE.Line(geom, contra
        ? new THREE.LineDashedMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.7, dashSize: 0.03, gapSize: 0.03 })
        : new THREE.LineBasicMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.85 }));
      if (contra) line.computeLineDistances();
      out.push(line);
    }
    return out;
  }, [focusTheme, themeOf, p.data, p.ends]);

  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
  const register = useLabelCollisions();

  return (
    <LabelCtx.Provider value={register}>
    <FadeIn morph={p.morph}>
      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
      <points geometry={nodes} material={nodeMat}
              onPointerMove={(e) => {
                const i = pick(e); if (i == null) return;
                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
              }}
              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
                                            hot={p.hoverKey === t.key}
                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
      {areas.map(({ a, at }) => <Diamond key={a.key} a={a} at={at} active={focusArea === a.key} hot={p.hoverKey === a.key}
                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
    </FadeIn>
    </LabelCtx.Provider>
  );
}

function ThemeHalo({ t, active, hot, label, onHover, onSelect, setCursor }: {
  t: ThemeNode; active: boolean; hot: boolean; label: boolean;
  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
}) {
  const r = 0.05 + Math.sqrt(t.comments) * 0.006;
  const lost = t.state === "lost", changed = t.state === "strengthened" || t.state === "new";
  const register = useContext(LabelCtx);
  const { k } = useSpread();   // the halo keeps its size when the spread opens the universe up
  return (
    <Billboard position={[t.x, t.y, t.z]} scale={k}>
      <mesh onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: t.title, sub: `Theme · ${t.comments} comments${t.state ? ` · ${t.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, t.key); }}
            onPointerOut={() => { setCursor(false); onHover(null, null); }}
            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "theme", key: t.key }, [t.x, t.y, t.z]); }}>
        <ringGeometry args={[r, r + (active ? 0.008 : 0.004), 48]} />
        <meshBasicMaterial color={lost ? "#f5a524" : "#ffffff"} transparent opacity={active ? 0.95 : changed ? 0.55 : 0.32} depthWrite={false} />
      </mesh>
      {label && (
        <Html position={[0, r + 0.06, 0]} center zIndexRange={[12, 0]}>
          <div className="theme-label" data-active={active ? "" : undefined}
               ref={register(`theme:${t.key}`, active || hot ? FOCUS : t.comments)}>{t.title}</div>
        </Html>
      )}
    </Billboard>
  );
}

function Diamond({ a, at, active, hot, onHover, onSelect, setCursor }: {
  a: AreaNode; at: [number, number, number]; active: boolean; hot: boolean;
  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
}) {
  const ref = useRef<THREE.Mesh>(null);
  const register = useContext(LabelCtx);
  useFrame((_, dt) => { if (ref.current) ref.current.rotation.y += dt * (active ? 1.6 : 0.4); });
  const quality = a.kind === "quality";
  const color = quality ? "#f5a524" : a.kind === "keep" ? "#eef1f5" : a.kind === "emerging" ? "#d95926" : "#3987e5";
  const size = 0.028 + Math.min(0.03, Math.sqrt(a.metrics.comments ?? 1) * 0.0012);
  const { k } = useSpread();
  return (
    <group position={at} scale={k}>
      <mesh ref={ref}
            onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: a.title, sub: quality ? "Quality hand-over" : `Requirement area · ${a.kind} · ${a.metrics.comments ?? 0} comments${a.state ? ` · ${a.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, a.key); }}
            onPointerOut={() => { setCursor(false); onHover(null, null); }}
            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "area", key: a.key }, at); }}>
        <octahedronGeometry args={[active ? size * 1.5 : size, 0]} />
        <meshBasicMaterial color={color} wireframe={a.state === "new" || quality} transparent opacity={active ? 1 : 0.9} />
      </mesh>
      {(active || (a.metrics.comments ?? 0) > 0) && (
        <Html position={[0, size + 0.05, 0]} center zIndexRange={[12, 0]}>
          <div className="area-label" data-active={active ? "" : undefined}
               ref={register(`area:${a.key}`, active || hot ? FOCUS : AREA + (a.metrics.comments ?? 0))}>{a.title}</div>
        </Html>
      )}
    </group>
  );
}

export type { ClusterNode };

toolUseResult.stdout:
// Moving through the scan volume. Spread scales the whole universe (layout positions) around a camera that stays put,
// while every mark keeps its size, so the space between contacts opens up on screen. The outer rings move past the
// view as it grows; scroll out or fly to reach them. Flying moves the camera and the orbit centre together:
// W/S forward and back, A/D sideways, Q/E down and up (Shift: faster), or hold the pad's buttons.
import { createContext, useContext, useEffect, useRef, type MutableRefObject, type PointerEvent as ReactPointerEvent } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { ArrowDown, ArrowUp, LocateFixed } from "lucide-react";
import * as THREE from "three";

export const SPREAD_MIN = 1, SPREAD_MAX = 4;
export const HOME: [number, number, number] = [0, 2.3, 5.3];

/** spread: layout scale; grow: how much marks grow with it (none); k: counter-scale for a mark inside the scaled world */
export interface Spread { spread: number; grow: number; k: number }
const make = (spread: number): Spread => ({ spread, grow: 1, k: 1 / spread });
export const spreadOf = make;
export const SpreadCtx = createContext<Spread>(make(1));
export const useSpread = () => useContext(SpreadCtx);

/** what the pad's buttons hold down; reset counts up once per press */
export interface NavInput { fwd: number; reset: number }
export const newNav = (): NavInput => ({ fwd: 0, reset: 0 });

const KEYS: Record<string, [number, number, number]> = {   // [forward, right, up]
  w: [1, 0, 0], s: [-1, 0, 0], a: [0, -1, 0], d: [0, 1, 0], e: [0, 0, 1], q: [0, 0, -1],
};
const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(TEXTAREA|SELECT)$/.test(t.tagName) ||
                               (t instanceof HTMLInputElement && !/^(range|checkbox|radio|button)$/.test(t.type)));

type Orbit = { target: THREE.Vector3; update: () => void };

export function Navigator({ spread, nav, fit }: { spread: number; nav: MutableRefObject<NavInput>; fit: () => number }) {
  const { camera } = useThree();
  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
  const held = useRef(new Set<string>());
  const fast = useRef(false);
  const home = useRef<{ t0: number; from: THREE.Vector3; fromT: THREE.Vector3 } | null>(null);
  const lastReset = useRef(nav.current.reset);

  useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target)) return;
      const key = e.key.toLowerCase();
      fast.current = e.shiftKey;
      if (KEYS[key]) { held.current.add(key); e.preventDefault(); }
    };
    const up = (e: KeyboardEvent) => { fast.current = e.shiftKey; held.current.delete(e.key.toLowerCase()); };
    const clear = () => held.current.clear();
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    window.addEventListener("blur", clear);
    return () => { window.removeEventListener("keydown", down); window.removeEventListener("keyup", up); window.removeEventListener("blur", clear); };
  }, []);

  const fwd = new THREE.Vector3(), right = new THREE.Vector3(), step = new THREE.Vector3();
  useFrame(({ clock }, dt) => {
    if (!controls) return;
    // reset: glide back to the opening view
    if (nav.current.reset !== lastReset.current) {
      lastReset.current = nav.current.reset;
      home.current = { t0: clock.elapsedTime, from: camera.position.clone(), fromT: controls.target.clone() };
    }
    if (home.current) {
      const h = home.current, p = Math.min(1, (clock.elapsedTime - h.t0) / 0.7), e = 1 - Math.pow(1 - p, 3);
      const goal = new THREE.Vector3(...HOME).setLength(fit());
      camera.position.lerpVectors(h.from, goal, e);
      controls.target.lerpVectors(h.fromT, new THREE.Vector3(), e);
      controls.update();
      if (p >= 1) home.current = null;
      return;
    }
    let f = nav.current.fwd, r = 0, u = 0;
    for (const k of held.current) { const [a, b, c] = KEYS[k]; f += a; r += b; u += c; }
    if (!f && !r && !u) return;
    camera.getWorldDirection(fwd);
    right.crossVectors(fwd, camera.up).normalize();
    const speed = 1.4 * spread * (fast.current ? 2.5 : 1) * Math.min(dt, 0.05);
    step.copy(fwd).multiplyScalar(f).addScaledVector(right, r).addScaledVector(camera.up, u).multiplyScalar(speed);
    camera.position.add(step);
    controls.target.add(step);
    controls.update();
  });
  return null;
}

/** Bottom-centre pad: the spread slider, hold-to-fly buttons and a reset. */
export function NavPad({ spread, onSpread, nav }: { spread: number; onSpread: (s: number) => void; nav: MutableRefObject<NavInput> }) {
  const hold = (dir: number) => ({
    onPointerDown: (e: ReactPointerEvent<HTMLButtonElement>) => { e.currentTarget.setPointerCapture(e.pointerId); nav.current.fwd = dir; },
    onPointerUp: () => { nav.current.fwd = 0; },
    onPointerCancel: () => { nav.current.fwd = 0; },
    onLostPointerCapture: () => { nav.current.fwd = 0; },
  });
  return (
    <div className="navpad" role="group" aria-label="Move through the universe">
      <label className="navpad-spread">
        <span>Spread</span>
        <input type="range" min={SPREAD_MIN} max={SPREAD_MAX} step={0.05} value={spread}
               onChange={(e) => onSpread(Number(e.target.value))} aria-valuetext={`${spread.toFixed(1)} times`} />
        <output className="num">{spread.toFixed(1)}×</output>
      </label>
      <div className="navpad-fly">
        <button type="button" title="Fly back (S)" aria-label="Fly back" {...hold(-1)}><ArrowDown size={14} /></button>
        <button type="button" title="Fly forward (W)" aria-label="Fly forward" {...hold(1)}><ArrowUp size={14} /></button>
        <button type="button" title="Reset view" aria-label="Reset view" onClick={() => { nav.current.reset++; }}><LocateFixed size={14} /></button>
      </div>
      <span className="navpad-hint">W/S fly · A/D side · Q/E down/up · right-drag pan · scroll zooms to cursor</span>
    </div>
  );
}
// Page 2 inside the scan volume: what the AI made of the raw evidence at the current checkpoint.
// Comment points have already flown into their clusters (the morph in Scene). This layer adds the structure on top:
// cluster nodes (blue = something to improve, white = something to keep; mark shape = track state: dot held,
// ring new, double ring strengthened, amber weakened, amber cross lost), theme halos around groups of clusters,
// potential requirement AREAS as diamonds floating above the themes they group, and — for the theme in focus —
// evidence arcs down to the exact research, study and option items on the rings.
import { createContext, useCallback, useContext, useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
import { Billboard, Html } from "@react-three/drei";
import * as THREE from "three";
import type { AreaNode, ClusterNode, Selection, StructurePayload, ThemeNode, TrackState } from "@/lib/types";
import type { Hover } from "../scan/Scene";
import { TYPE_COLOR } from "../scan/colors";
import { useSpread } from "../scan/navigate";

export const AREA_Y = 1.15;
const STATE_CODE: Record<TrackState, number> = { held: 0, new: 1, strengthened: 2, weakened: 3, lost: 4 };
const SRC_COLOR: Record<string, string> = { research: TYPE_COLOR.research, study: TYPE_COLOR.study, option: TYPE_COLOR.option };

const NODE_VERT = /* glsl */ `
attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
uniform float uScale, uShow, uHover;
varying float vState; varying float vPol; varying float vHov;
void main() {
  vState = aState; vPol = aPol; vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = aSize * uScale * (1.0 + vHov * 0.6) * uShow / -mv.z;
}`;
const NODE_FRAG = /* glsl */ `
uniform float uShow;
varying float vState; varying float vPol; varying float vHov;
void main() {
  vec2 c = gl_PointCoord - 0.5; float r = length(c);
  if (r > 0.5) discard;
  float dot = smoothstep(0.5, 0.44, r);
  float ring = smoothstep(0.5, 0.45, r) * smoothstep(0.34, 0.39, r);
  float dbl = ring + smoothstep(0.27, 0.23, r) * smoothstep(0.15, 0.19, r);
  float cross = (abs(c.x - c.y) < 0.06 || abs(c.x + c.y) < 0.06) && r < 0.45 ? 1.0 : 0.0;
  float a = vState < 0.5 ? dot : vState < 1.5 ? ring : vState < 2.5 ? dbl : vState < 3.5 ? dot : cross;
  vec3 base = vPol > 0.5 ? vec3(0.224, 0.529, 0.898) : vec3(0.93, 0.95, 0.97);
  vec3 amber = vec3(0.96, 0.65, 0.14);
  vec3 col = vState > 2.5 ? amber : base;
  col = mix(col, vec3(1.0), vHov);
  gl_FragColor = vec4(col, a * uShow * (vState > 3.5 ? 0.8 : 0.95));
}`;

/** Fades every material below it with the morph (structure appears as the comments arrive). The labels are DOM
 *  overlays (drei <Html>) that ignore `visible`, so the same fade goes to them as a CSS variable on the canvas
 *  container they live in, and they are taken out entirely at 0: on the Evidence page none of them show. */
function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
  const ref = useRef<THREE.Group>(null);
  // the element drei <Html> mounts its labels into (the event source, else the canvas's parent)
  const host = useThree((s) => ((s.events.connected as HTMLElement | undefined) ?? s.gl.domElement.parentElement) as HTMLElement | null);
  const last = useRef(-1);
  useFrame(() => {
    const g = ref.current;
    if (!g) return;
    const a = Math.max(0, (morph.current - 0.45) / 0.55);
    g.visible = a > 0.01;
    if (host && Math.abs(a - last.current) > 0.004) {
      last.current = a;
      host.style.setProperty("--structure-fade", a.toFixed(3));
      host.toggleAttribute("data-structure-off", a <= 0.01);
    }
    g.traverse((o) => {
      const mat = (o as THREE.Mesh).material;
      if (!mat) return;
      for (const m of Array.isArray(mat) ? mat : [mat]) {
        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uShow) m.uniforms.uShow.value = a; continue; }
        m.userData.baseOpacity ??= m.opacity;
        m.transparent = true;
        m.opacity = m.userData.baseOpacity * a;
      }
    });
  });
  return <group ref={ref}>{children}</group>;
}

/* ------------------------------------------------------------------------------------------- label collisions */
// Labels are placed in priority order: the label in focus or under the pointer first, then requirement areas by
// comments, then themes by comments. A label whose screen box would overlap one already placed is hidden (visibility
// only, so it stays measurable) until the view turns or its node is hovered. Checked a few times a second.
type Register = (key: string, prio: number) => (el: HTMLDivElement | null) => void;
const LabelCtx = createContext<Register>(() => () => {});
const PAD = 3;

function useLabelCollisions() {
  const labels = useRef(new Map<string, { el: HTMLDivElement; prio: number }>());
  const tick = useRef(0);
  const register = useCallback<Register>((key, prio) => (el) => {
    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
  }, []);
  useFrame(() => {
    if (tick.current++ % 6) return;
    const placed: DOMRect[] = [];
    const list = [...labels.current.values()].sort((a, b) => b.prio - a.prio);
    for (const { el, prio } of list) {
      const r = el.getBoundingClientRect();
      if (!r.width) continue;
      const hit = prio < FOCUS && placed.some((q) =>
        r.left < q.right + PAD && r.right > q.left - PAD && r.top < q.bottom + PAD && r.bottom > q.top - PAD);
      el.toggleAttribute("data-collide", hit);
      if (!hit) placed.push(r);
    }
  });
  return register;
}
const FOCUS = 1e9;          // focused or hovered: always shown
const AREA = 1e6;           // areas outrank themes

interface Props {
  data: StructurePayload;
  morph: MutableRefObject<number>;
  dpr: number;
  selected: Selection | null;
  hoverKey: string | null;
  ends: (type: string, id: string) => [number, number, number] | null;
  onHover: (h: Hover | null, key?: string | null) => void;
  onSelect: (s: Selection, at: [number, number, number]) => void;
  setCursor: (on: boolean) => void;
}

export function StructureLayer(p: Props) {
  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);


  /* cluster nodes */
  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
  }), [p.dpr]);
  const nodes = useMemo(() => {
    const n = clusters.length;
    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
    clusters.forEach((c, i) => {
      pos.set([c.x, c.y, c.z], i * 3);
      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
    });
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
    g.computeBoundingSphere();
    return g;
  }, [clusters]);
  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));

  /* cluster → theme lines */
  const memberLines = useMemo(() => {
    const v: number[] = [];
    for (const c of clusters) {
      const t = c.theme ? themeOf[c.theme] : null;
      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
    }
    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
  }, [clusters, themeOf]);

  /* requirement areas float on a ring above the galaxy: each at an evenly spaced slot, in the order of its themes'
     bearing, so labels never pile up over the centre; stems tie every area to its themes below */
  const areas = useMemo(() => {
    const placed: { a: AreaNode; ts: ThemeNode[]; bearing: number }[] = [];
    for (const a of p.data.areas) {
      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
      if (!ts.length) continue;
      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
      placed.push({ a, ts, bearing: Math.atan2(z, x) });
    }
    placed.sort((m, n) => m.bearing - n.bearing);
    const n = placed.length || 1;
    return placed.map(({ a, ts }, i) => {
      const ang = (i / n) * Math.PI * 2 - Math.PI / 2;
      const r = a.kind === "quality" ? 0.35 : 1.05;
      const y = a.kind === "quality" ? AREA_Y - 0.25 : AREA_Y + (i % 2) * 0.12;   // alternate heights for neighbours
      return { a, ts, at: [r * Math.cos(ang), y, r * Math.sin(ang)] as [number, number, number] };
    });
  }, [p.data, themeOf]);
  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
  const stems = useMemo(() => {
    const v: number[] = [], hot: number[] = [];
    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
    return { all: g(v), hot: g(hot) };
  }, [areas, focusArea]);

  /* evidence arcs for the theme in focus */
  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
  const arcs = useMemo(() => {
    if (!focusTheme || !themeOf[focusTheme]) return [];
    const t = themeOf[focusTheme];
    const out: THREE.Line[] = [];
    for (const e of p.data.edges) {
      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
      const end = p.ends(e.src_type, e.src_id);
      if (!end) continue;
      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
      const pts = new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(40);
      const geom = new THREE.BufferGeometry().setFromPoints(pts);
      const contra = e.relation === "contradicts";
      const line = new THREE.Line(geom, contra
        ? new THREE.LineDashedMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.7, dashSize: 0.03, gapSize: 0.03 })
        : new THREE.LineBasicMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.85 }));
      if (contra) line.computeLineDistances();
      out.push(line);
    }
    return out;
  }, [focusTheme, themeOf, p.data, p.ends]);

  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
  const register = useLabelCollisions();

  return (
    <LabelCtx.Provider value={register}>
    <FadeIn morph={p.morph}>
      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
      <points geometry={nodes} material={nodeMat}
              onPointerMove={(e) => {
                const i = pick(e); if (i == null) return;
                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
              }}
              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
                                            hot={p.hoverKey === t.key}
                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
      {areas.map(({ a, at }) => <Diamond key={a.key} a={a} at={at} active={focusArea === a.key} hot={p.hoverKey === a.key}
                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
    </FadeIn>
    </LabelCtx.Provider>
  );
}

function ThemeHalo({ t, active, hot, label, onHover, onSelect, setCursor }: {
  t: ThemeNode; active: boolean; hot: boolean; label: boolean;
  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
}) {
  const r = 0.05 + Math.sqrt(t.comments) * 0.006;
  const lost = t.state === "lost", changed = t.state === "strengthened" || t.state === "new";
  const register = useContext(LabelCtx);
  const { k } = useSpread();   // the halo keeps its size when the spread opens the universe up
  return (
    <Billboard position={[t.x, t.y, t.z]} scale={k}>
      <mesh onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: t.title, sub: `Theme · ${t.comments} comments${t.state ? ` · ${t.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, t.key); }}
            onPointerOut={() => { setCursor(false); onHover(null, null); }}
            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "theme", key: t.key }, [t.x, t.y, t.z]); }}>
        <ringGeometry args={[r, r + (active ? 0.008 : 0.004), 48]} />
        <meshBasicMaterial color={lost ? "#f5a524" : "#ffffff"} transparent opacity={active ? 0.95 : changed ? 0.55 : 0.32} depthWrite={false} />
      </mesh>
      {label && (
        <Html position={[0, r + 0.06, 0]} center zIndexRange={[12, 0]}>
          <div className="theme-label" data-active={active ? "" : undefined}
               ref={register(`theme:${t.key}`, active || hot ? FOCUS : t.comments)}>{t.title}</div>
        </Html>
      )}
    </Billboard>
  );
}

function Diamond({ a, at, active, hot, onHover, onSelect, setCursor }: {
  a: AreaNode; at: [number, number, number]; active: boolean; hot: boolean;
  onHover: Props["onHover"]; onSelect: Props["onSelect"]; setCursor: Props["setCursor"];
}) {
  const ref = useRef<THREE.Mesh>(null);
  const register = useContext(LabelCtx);
  useFrame((_, dt) => { if (ref.current) ref.current.rotation.y += dt * (active ? 1.6 : 0.4); });
  const quality = a.kind === "quality";
  const color = quality ? "#f5a524" : a.kind === "keep" ? "#eef1f5" : a.kind === "emerging" ? "#d95926" : "#3987e5";
  const size = 0.028 + Math.min(0.03, Math.sqrt(a.metrics.comments ?? 1) * 0.0012);
  const { k } = useSpread();
  return (
    <group position={at} scale={k}>
      <mesh ref={ref}
            onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: a.title, sub: quality ? "Quality hand-over" : `Requirement area · ${a.kind} · ${a.metrics.comments ?? 0} comments${a.state ? ` · ${a.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, a.key); }}
            onPointerOut={() => { setCursor(false); onHover(null, null); }}
            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "area", key: a.key }, at); }}>
        <octahedronGeometry args={[active ? size * 1.5 : size, 0]} />
        <meshBasicMaterial color={color} wireframe={a.state === "new" || quality} transparent opacity={active ? 1 : 0.9} />
      </mesh>
      {(active || (a.metrics.comments ?? 0) > 0) && (
        <Html position={[0, size + 0.05, 0]} center zIndexRange={[12, 0]}>
          <div className="area-label" data-active={active ? "" : undefined}
               ref={register(`area:${a.key}`, active || hot ? FOCUS : AREA + (a.metrics.comments ?? 0))}>{a.title}</div>
        </Html>
      )}
    </group>
  );
}

export type { ClusterNode };

