export function AuditPanel() {
  const { pathname } = useLocation();
  const { cp } = useCheckpoint();
  const [open, setOpen] = useState(false);
  const [all, setAll] = useState(false);
  const [history, setHistory] = useState(false);
  const [hidden, setHidden] = useState<Set<Who>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const page = pathname.startsWith("/structure") ? "structure" : "evidence";
  const scope = all ? "all" : page;

content.content:
  const scope = all ? "all" : page;
  const withHistory = all && history;

  const q = useInfiniteQuery({
    queryKey: ["audit-feed", scope, cp, withHistory],
    enabled: open,
    initialPageParam: "",
    queryFn: ({ pageParam }) => api.get<Page>(`/api/audit/feed?scope=${scope}&cp=${cp}&limit=400${withHistory ? "&history=true" : ""}${pageParam ? `&before=${encodeURIComponent(pageParam)}` : ""}`),
    getNextPageParam: (last) => (last.more && last.items.length ? last.items[last.items.length - 1].ts : undefined),
    refetchInterval: open ? 5000 : false,
  });
  const rows = useMemo(() => q.data?.pages.flatMap((p) => p.items) ?? [], [q.data]);
  const counts = useMemo(() => {
    const c: Record<Who, number> = { ai: 0, system: 0, human: 0 };
    for (const r of rows) c[r.actor_type] = (c[r.actor_type] ?? 0) + 1;
    return c;
  }, [rows]);
  const items = useMemo(() => fold(rows.filter((r) => !hidden.has(r.actor_type))), [rows, hidden]);
  const oldest = rows.length ? Date.parse(rows[rows.length - 1].ts) : 0;

  useEffect(() => {
    if (!open) return;
    // Esc closes the trail first; captured and stopped so it doesn't also clear the scan's filters or selection
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopImmediatePropagation(); setOpen(false); } };
    window.addEventListener("keydown", onKey, { capture: true });
    return () => window.removeEventListener("keydown", onKey, { capture: true });
  }, [open]);

  const toggleWho = (w: Who) => setHidden((h) => { const n = new Set(h); if (n.has(w)) n.delete(w); else n.add(w); return n; });
  const toggleFold = (id: string) => setExpanded((x) => { const n = new Set(x); if (n.has(id)) n.delete(id); else n.add(id); return n; });

  let lastDay = "";
  return (
    <>
      <button className="audit-btn" aria-expanded={open} aria-controls="audit-panel" onClick={() => setOpen((o) => !o)}>
        <History size={14} aria-hidden /> Audit
      </button>
      {open && (
        <aside id="audit-panel" className="audit" aria-label="Audit trail">
          <button className="audit-close" onClick={() => setOpen(false)} aria-label="Close audit"><X size={16} /></button>
          <header className="audit-head">
            <span className="audit-layer"><History size={14} aria-hidden />Audit trail</span>
            <p className="audit-what">{WHAT[scope]}</p>
            <div className="audit-tabs" role="tablist">
              <button role="tab" aria-selected={!all} onClick={() => setAll(false)}>{`${page === "structure" ? "Structure" : "Evidence"} · ${CP_LABEL[cp] ?? cp}`}</button>
              <button role="tab" aria-selected={all} onClick={() => setAll(true)}>Everything</button>
            </div>
            <div className="audit-who-chips" aria-label="Who acted">
              {WHO_ORDER.filter((w) => counts[w]).map((w) => (
                <button key={w} className="audit-chip" aria-pressed={!hidden.has(w)} onClick={() => toggleWho(w)}>
                  <i className="audit-mark" data-who={w} aria-hidden />{WHO[w]}<span className="audit-chip-n">{counts[w].toLocaleString("en-US")}</span>
                </button>
              ))}
            </div>
          </header>

          <ol className="audit-list">
            {q.isPending && <li className="audit-empty label">Loading…</li>}
            {!q.isPending && items.length === 0 && <li className="audit-empty label">Nothing recorded here yet.</li>}
            {items.map((it) => {
              const head = it.day !== lastDay ? (lastDay = it.day) : null;
              const f = it.rows[0], n = it.rows.length, last = it.rows[n - 1];
              const milestone = f.kind === "run";
              const isOpen = expanded.has(f.id);
              // the last fold may continue into rows not loaded yet: say so rather than show a partial total as the total
              const partial = n > 1 && q.hasNextPage && Date.parse(last.ts) - oldest <= GAP;
              const meta = [WHO[f.actor_type], f.model, n > 1 ? `${n}${partial ? "+" : ""} steps` : null,
                            n > 1 ? `${partial ? "…" : time(last.ts)}–${time(f.ts)}` : time(f.ts)].filter(Boolean).join(" · ");
              const body = (
                <>
                  <span className="audit-text">{partial ? "Latest: " : ""}{foldText(it.rows)}</span>
                  <span className="audit-meta">{meta}</span>
                </>
              );
              return (
                <li key={f.id} className="audit-item" data-milestone={milestone ? "" : undefined}>
                  {head && <div className="audit-day">{head}</div>}
                  <div className="audit-row">
                    <i className="audit-mark" data-who={f.actor_type} data-milestone={milestone ? "" : undefined} aria-hidden />
                    {n > 1 ? (
                      <button className="audit-body audit-fold" aria-expanded={isOpen} onClick={() => toggleFold(f.id)}>
                        {body}<ChevronRight className="audit-chev" size={14} aria-hidden />
                      </button>
                    ) : <div className="audit-body">{body}</div>}
                    {f.checkpoint && <span className="audit-cp">{CP_LABEL[f.checkpoint] ?? f.checkpoint}</span>}
                  </div>
                  {isOpen && (
                    <ol className="audit-steps">
                      {it.rows.map((r) => <li key={r.id}><span className="audit-step-t">{time(r.ts)}</span>{text(r)}</li>)}
                    </ol>
                  )}
                </li>
              );
            })}
          </ol>
          {all && !q.hasNextPage && !q.isPending && (
            <button className="audit-more" aria-pressed={history} onClick={() => setHistory((h) => !h)}>
              {history ? "Hide history before the checkpoint rebuild" : "Show history before the checkpoint rebuild"}
            </button>
          )}
          {q.hasNextPage && (
            <button className="audit-more" onClick={() => q.fetchNextPage()} disabled={q.isFetchingNextPage}>
              {q.isFetchingNextPage ? "Loading…" : "Show older"}
            </button>
          )}
        </aside>
      )}
    </>
  );
}
// Bottom-left dock: the Guide explains the screen (a legend drawn with the scene's own marks) and, once something is
// opened, what that kind of item is and how the AI uses it. On Structure the Agent panel sits next to it. Each is a
// pill like the Audit button; clicking one opens its panel above the pills and closes the other, clicking the open one
// closes it. Which one is open (or none) is remembered per browser.
import { useEffect, useState, type ReactNode } from "react";
import { BookOpen, Bot } from "lucide-react";
import type { Selection } from "@/lib/types";
import { TYPE_COLOR } from "@/screens/scan/colors";
import "./guide.css";

type Mode = "scan" | "structure";
type MarkKind =
  | "comment" | "research" | "study" | "option" | "sales" | "sales-fc" | "public" | "held" | "new"
  | "improve" | "keep" | "strengthened" | "weakened" | "lost" | "theme" | "area-improve" | "area-keep"
  | "area-emerging" | "area-quality" | "area-new" | "arc" | "arc-contra" | "sector";
interface Row { mark: MarkKind; name: string; text: string }
interface Page { title: string; lead?: string; rows?: Row[]; uses?: string; notes?: string[] }

const BLUE = "#3987e5", INK = "#f2f4f7", AMBER = "#f5a524";

/** The scene's marks in miniature, so the legend looks exactly like what it explains. */
function Mark({ kind }: { kind: MarkKind }) {
  const s = { width: 18, height: 18, viewBox: "0 0 18 18", "aria-hidden": true, className: "gmark" } as const;
  switch (kind) {
    case "comment": return <svg {...s}><circle cx="5" cy="7" r="2" fill={BLUE} /><circle cx="11.5" cy="5" r="2" fill={BLUE} opacity=".7" /><circle cx="10" cy="12" r="2.4" fill={BLUE} /></svg>;
    case "research": return <svg {...s}><path d="M2 12a8 8 0 0 1 14 0" fill="none" stroke="#fff" strokeOpacity=".35" strokeDasharray="1.5 2" /><circle cx="9" cy="6" r="2.4" fill={TYPE_COLOR.research} /></svg>;
    case "study": return <svg {...s}><path d="M2 11h14" stroke="#fff" strokeOpacity=".2" /><path d="M5 11V6M9 11v4M13 11V4" stroke={TYPE_COLOR.study} strokeWidth="1.5" /></svg>;
    case "option": return <svg {...s}>{[3.5, 7, 10.5, 14].map((x) => <circle key={x} cx={x} cy="9" r="1.3" fill={TYPE_COLOR.option} />)}</svg>;
    case "sales": return <svg {...s}><rect x="5" y="6" width="2.5" height="9" fill={TYPE_COLOR.sales} /><rect x="10.5" y="3" width="2.5" height="12" fill={TYPE_COLOR.sales} /></svg>;
    case "sales-fc": return <svg {...s}><rect x="7.5" y="3.5" width="3" height="11" fill="none" stroke={TYPE_COLOR.sales} /></svg>;
    case "public": return <svg {...s}><circle cx="9" cy="9" r="4" fill="none" stroke={TYPE_COLOR.study} strokeWidth="1.5" /></svg>;
    case "held": return <svg {...s}><circle cx="9" cy="9" r="4" fill={INK} /></svg>;
    case "new": return <svg {...s}><circle cx="9" cy="9" r="4" fill="none" stroke={INK} strokeWidth="1.5" /></svg>;
    case "improve": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill="none" stroke={BLUE} strokeWidth="2" /></svg>;
    case "keep": return <svg {...s}><circle cx="9" cy="9" r="4.5" fill="none" stroke={INK} strokeWidth="2" /></svg>;
    case "strengthened": return <svg {...s}><circle cx="9" cy="9" r="6" fill="none" stroke={INK} strokeWidth="1.3" /><circle cx="9" cy="9" r="2.8" fill="none" stroke={INK} strokeWidth="1.3" /></svg>;
    case "weakened": return <svg {...s}><circle cx="9" cy="9" r="4" fill={AMBER} /></svg>;
    case "lost": return <svg {...s}><path d="M5.5 5.5l7 7M12.5 5.5l-7 7" stroke={AMBER} strokeWidth="1.6" /></svg>;
    case "theme": return <svg {...s}><circle cx="9" cy="9" r="6.5" fill="none" stroke="#fff" strokeOpacity=".55" /></svg>;
    case "area-improve": case "area-keep": case "area-emerging": case "area-quality": case "area-new": {
      const c = kind === "area-keep" ? "#eef1f5" : kind === "area-emerging" ? TYPE_COLOR.research : kind === "area-quality" ? AMBER : BLUE;
      const wire = kind === "area-new" || kind === "area-quality";
      return <svg {...s}><path d="M9 2.5l5 6.5-5 6.5-5-6.5z" fill={wire ? "none" : c} stroke={c} strokeWidth="1.2" /></svg>;
    }
    case "arc": return <svg {...s}><path d="M3 15Q9 1 15 15" fill="none" stroke={TYPE_COLOR.research} strokeWidth="1.4" /></svg>;
    case "arc-contra": return <svg {...s}><path d="M3 15Q9 1 15 15" fill="none" stroke={TYPE_COLOR.study} strokeWidth="1.4" strokeDasharray="2 2" /></svg>;
    case "sector": return <svg {...s}><path d="M3 13A8 8 0 0 1 9 5" fill="none" stroke="#fff" strokeOpacity=".5" /><path d="M10.5 5A8 8 0 0 1 15 9" fill="none" stroke="#fff" strokeOpacity=".5" /></svg>;
  }
}

