.hovercard {
  position: fixed; z-index: 30; width: 320px; padding: 14px 20px; display: grid; gap: 8px; pointer-events: none;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 14px, #000 calc(100% - 14px), transparent), linear-gradient(to bottom, transparent, #000 10px, #000 calc(100% - 10px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
}
.hovercard p { font-size: 13px; line-height: 1.45; color: var(--ink); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.hovercard-meta { display: flex; align-items: center; gap: 10px; font-size: var(--t-micro); color: var(--ink-3); }
/* the inspector: same frameless dark field as the audit trail and the dock (no box, border or shadow); it feathers out
   at its edges, so content scrolling past the top or bottom fades into the volume instead of being cut */
.sheet {
  position: fixed; top: calc(var(--edge) + 46px); right: var(--edge); z-index: 25; width: min(440px, calc(100vw - 32px));
  max-height: calc(100vh - 2 * var(--edge) - 196px); overflow: auto; padding: 22px 26px 26px; display: grid; gap: 22px;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 28px, #000 calc(100% - 12px), transparent), linear-gradient(to bottom, transparent, #000 14px, #000 calc(100% - 22px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  animation: sheet-in var(--med) var(--ease);
}
/* inside the inspector, the AI's findings and notes are not boxed either: they hang off a hairline rail, like the audit trail */
.sheet .sig, .sheet .note { padding: 2px 0 2px 12px; border: 0; border-left: 1px solid var(--hair-2); border-radius: 0; background: none; }
@keyframes sheet-in { from { opacity: 0; transform: translateY(-6px); } }
.sheet-skel span:last-child { width: 60%; }

@media (max-width: 760px) {
  .hud-tl { left: 16px; top: 16px; max-width: calc(100vw - 32px); gap: 12px; }
  .readout { display: flex; flex-wrap: wrap; gap: 10px 20px; }
  .filters { max-width: none; }
  .readout .num { font-size: 22px; }
  .sheet { top: auto; bottom: 140px; }
}

/* navigation pad, bottom centre between the dock and the checkpoint control: spread slider, hold-to-fly, reset */
.navpad {
  position: fixed; left: 50%; bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%); z-index: 14;
  display: grid; grid-template-columns: auto auto; align-items: center; justify-items: center; gap: 8px 14px;
}
.navpad-spread { display: inline-flex; align-items: center; gap: 10px; font-size: var(--t-label); color: var(--ink-2); }
.navpad-spread input { width: 160px; accent-color: var(--sweep-hi); }
.navpad-spread output { min-width: 4ch; font-size: var(--t-label); color: var(--ink); text-align: right; }
.navpad-fly { display: inline-flex; gap: 6px; }
.navpad-fly button {
  width: 32px; height: 32px; display: grid; place-items: center; border-radius: 99px; color: var(--ink-2);
  background: rgba(0, 0, 0, 0.6); border: 1px solid var(--hair); touch-action: none;
  transition: color var(--fast), border-color var(--fast), background var(--fast);
}
.navpad-fly button:hover { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.navpad-fly button:active { color: var(--ink); background: var(--sweep-wash); border-color: var(--sweep); }
.navpad-hint { grid-column: 1 / -1; font-size: var(--t-micro); color: var(--ink-3); white-space: nowrap; pointer-events: none; }
@media (max-width: 1100px) { .navpad-hint { display: none; } }
@media (max-width: 760px) {
  .navpad { bottom: auto; top: calc(var(--edge) + 48px); grid-template-columns: auto; }
  .navpad-spread input { width: 120px; }
}
