/* Bottom-left dock: a row of pills (Guide, and Agent on Structure) styled like the Audit button, and the open one's
   panel above them on the same frameless feathered black field as the audit trail, 300px wide like the checkpoint
   timeline in the opposite corner. Only one panel is open at a time. */
.dock {
  position: fixed; left: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 12;
  width: 300px; display: grid; gap: 12px; justify-items: start;
}
.dock-pills { display: flex; gap: 8px; }
.dock-pill {
  height: 32px; display: inline-flex; align-items: center; gap: 6px; padding: 0 14px 0 12px; border-radius: 99px;
  font-size: 13px; color: var(--ink-2); background: rgba(0, 0, 0, 0.6); border: 1px solid var(--hair);
  transition: color var(--fast), border-color var(--fast), background var(--fast);
}
.dock-pill:hover { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.dock-pill[aria-expanded="true"] { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.06); }
.dock-live { width: 6px; height: 6px; margin-left: 2px; border-radius: 50%; background: var(--ink); animation: agent-pulse 1.4s ease-out infinite; }
.dock-body {
  justify-self: stretch; max-height: min(46vh, 420px); overflow-y: auto; padding: 12px 14px 14px; margin: -12px -14px 0;
  background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 14px, #000 calc(100% - 14px), transparent), linear-gradient(to bottom, transparent, #000 12px, #000 calc(100% - 12px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  animation: dock-in var(--med) var(--ease);
}
@keyframes dock-in { from { opacity: 0; transform: translateY(4px); } }

/* the agent panel lives inside the dock on Structure */
.dock .agent { position: static; width: auto; }
.dock .agent-title { display: none; }

/* guide */
.guide { display: grid; gap: 10px; }
.guide-title { font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.guide-lead { font-size: var(--t-label); line-height: 1.5; color: var(--ink-2); }
.guide-uses { display: grid; gap: 4px; }
.guide-uses p { font-size: var(--t-label); line-height: 1.5; color: var(--ink-2); }
.guide-rows { list-style: none; margin: 2px 0 0; padding: 0; display: grid; gap: 8px; }
.guide-rows li { display: grid; grid-template-columns: 18px 1fr; gap: 10px; align-items: start; font-size: var(--t-label); line-height: 1.45; color: var(--ink-3); }
.guide-rows b { font-weight: 500; color: var(--ink-2); }
.gmark { margin-top: 0; }
.guide-notes { list-style: none; margin: 2px 0 0; padding: 8px 0 0; border-top: 1px solid var(--hair); display: grid; gap: 4px; }
.guide-notes li { font-size: var(--t-micro); line-height: 1.45; color: var(--ink-3); }

@media (max-width: 760px) { .dock { left: 16px; right: 16px; width: auto; bottom: 200px; } .dock-body { max-height: 32vh; } }
/* Evidence / Structure: two pill tabs in the chip style of the filters and the Audit pill (32px, hairline, no glass box) */
.pageswitch { position: fixed; top: var(--edge); left: 50%; transform: translateX(-50%); z-index: 20; display: flex; gap: 6px; }
.pageswitch a { height: 32px; display: inline-flex; align-items: center; padding: 0 15px; border-radius: 99px; border: 1px solid var(--hair);
  background: rgba(0, 0, 0, 0.6); font-size: 13px; font-weight: 600; letter-spacing: 0.04em; color: var(--ink-3); text-decoration: none;
  transition: color var(--fast), border-color var(--fast), background var(--fast); }
.pageswitch a:hover { color: var(--ink); border-color: var(--hair-2); }
.pageswitch a.active { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.07); }
/* brand: the shark-nose mark + wordmark, left of the tabs; text only, never a pill */
.pageswitch .brand { display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px 0 2px; color: var(--ink); user-select: none; }
.pageswitch .brand-name { font-size: 15px; font-weight: 650; letter-spacing: 0.01em; }
@media (max-width: 760px) { .pageswitch { top: auto; bottom: 150px; } }
/* Checkpoint control: frameless at the bottom-right edge, mirroring the key at the bottom-left. Fixed width and a
