        <span className="ladder-rail" aria-hidden />
        {placed.map(({ k, l, at }) => {
          const choosable = k !== "baseline";
          const rec = row.recommended === k, mine = chosen === k, picking = pick === k;
          const inner = (
            <>
              <span className="ladder-val">{l.basis === "gap" ? "?" : fmtLevel(l.value, unit)}</span>
