.dseg-name { padding: 0 6px 0 9px; }
.dseg button { height: 22px; padding: 0 10px; border-radius: 99px; font-size: var(--t-label); color: var(--ink-3); transition: color var(--fast), background var(--fast); white-space: nowrap; }
.dseg button:hover { color: var(--ink); }
.dseg button[aria-checked="true"] { color: var(--ink); background: rgba(255, 255, 255, 0.09); }
.dchips { display: flex; flex-wrap: wrap; gap: 6px; }
.dchip {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 99px; border: 1px solid var(--hair);
  background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); color: var(--ink-2); transition: border-color var(--fast), color var(--fast);
